Section Inner.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 x5 x7 x8 x11 x13 x14 x16 x17 x18 x19 x20 x22 x23 x24 x25 x26 x27 x28 x29 : word).
  Variables (m : amem) (SPR : Z) (js : list byte) (pos n b : Z).
  Variable POST : machine_state -> Prop.
  (* [comment removed for export] *)
  Hypothesis B1 : le1 x1 = [Z_to_bv 8 b].
  Hypothesis B8 : le1 x8 = [Z_to_bv 8 b].
  Hypothesis B22 : le1 x22 = [Z_to_bv 8 b].
  Hypothesis B23 : le1 x23 = [Z_to_bv 8 b].
  Hypothesis B24 : le1 x24 = [Z_to_bv 8 b].
  Hypothesis B25 : le1 x25 = [Z_to_bv 8 b].
  Hypothesis B26 : le1 x26 = [Z_to_bv 8 b].
  Hypothesis B27 : le1 x27 = [Z_to_bv 8 b].
  Hypothesis BSP : ablk SPR (SPR + zlen js).
  Hypothesis HPOS : 0 <= pos.
  Hypothesis ZS : zshadow m SPR (zlen js).
  Hypothesis RS : rng RNG SPR (zlen js).
  Hypothesis RSS : rng RNG (shad SPR) (nshad (zlen js + SPR mod 8)).

  Notation STI pc mm x9 x10 x12 x15 x21 x30 x31 :=
    (MS (mkR x1 sp gp tp x5 (Z_to_bv 64 2147450880) x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27
             x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  Lemma sp_innerA : forall f spr i r m1 (x9 x10 x12 : word),
    spread_inner f spr pos i n b = Ok r ->
    8 <= i < n -> n < 2^31 -> length js = length spr ->
    u8arr asegs m1 SPR (omerge js spr) ->
    munch [(SPR, SPR + zlen js)] m m1 -> wmono asegs m m1 -> mem_inv asegs m1 ->
    (forall m2 (y9 y10 y12 y15 y30 y31 : word), u8arr asegs m2 SPR (omerge js r) -> length r = length spr ->
       munch [(SPR, SPR + zlen js)] m m2 -> wmono asegs m m2 -> mem_inv asegs m2 ->
       evtF asegs RNG POST (STI 0x95848 m2 y9 y10 y12 y15 (Z_to_bv 64 n) y30 y31)) ->
    evtF asegs RNG POST (STI 0x958f0 m1 x9 x10 x12 (Z_to_bv 64 (SPR + (pos + i))) (Z_to_bv 64 n)
                             (Z_to_bv 64 i) (Z_to_bv 64 (SPR + (pos + i)))).
