Section Outer.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x5 x7 x16 : word).
  Variables (m : amem) (NC SPR WK2 : Z) (nc : list Z) (M1 : Z) (js : list byte).
  Variable POST : machine_state -> Prop.
  Hypothesis HM1 : 1 <= M1 <= 256.
  Hypothesis HNCL : M1 <= zlen nc.
  Hypothesis HNCR : Forall (fun c => - 32768 <= c < 32768) nc.
  Hypothesis BNC : ablk NC (NC + 2 * zlen nc).
  Hypothesis BSP : ablk SPR (SPR + zlen js).
  Hypothesis DNS : NC + 2 * zlen nc <= SPR \/ SPR + zlen js <= NC.
  Hypothesis NCB0 : bytes_at asegs m NC (u16s (map (Z_to_bv 64) nc)).     (* [comment removed for export] *)
  Hypothesis ZN : zshadow m NC (2 * zlen nc).
  Hypothesis ZS : zshadow m SPR (zlen js).
  Hypothesis RN : rng RNG NC (2 * zlen nc).
  Hypothesis RNS : rng RNG (shad NC) (nshad (2 * zlen nc + NC mod 8)).
  Hypothesis RS : rng RNG SPR (zlen js).
  Hypothesis RSS : rng RNG (shad SPR) (nshad (zlen js + SPR mod 8)).

  Definition spA_inv (m1 : amem) (spr : list (option Z)) : Prop :=
    u8arr asegs m1 SPR (omerge js spr) /\ munch [(SPR, SPR + zlen js)] m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1.

  Notation STO pc mm x1 x8 x9 x10 x12 x15 x17 x21 x22 x23 x24 x25 x26 x27 x29 x30 x31 :=
    (MS (mkR x1 sp gp tp x5 (Z_to_bv 64 2147450880) x7 x8 x9 x10 (Z_to_bv 64 NC) x12 (Z_to_bv 64 WK2) (Z_to_bv 64 9) x15 x16 x17
             (Z_to_bv 64 M1) (Z_to_bv 64 (SPR + 8)) (Z_to_bv 64 16843009) x21 x22 x23 x24 x25 x26 x27 (Z_to_bv 64 SPR) x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  Lemma sp_outerA : forall f s spr pos r m1 (x1 x9 x10 x12 x15 x21 x22 x23 x24 x25 x26 x27 x30 x31 : word),
    spread_loop nc f s spr pos = Ok r ->
    Z.of_nat f = M1 - s -> 0 <= s < M1 -> 0 <= pos < 2^64 -> length spr = length js ->
    spA_inv m1 spr ->
    (forall m2 (y1 y8 y9 y10 y12 y15 y17 y21 y22 y23 y24 y25 y26 y27 y30 y31 : word), spA_inv m2 r -> length r = length js ->
       evtF asegs RNG POST (STO 0x95a44 m2 y1 y8 y9 y10 y12 y15 y17 y21 y22 y23 y24 y25 y26 y27 (Z_to_bv 64 M1) y30 y31)) ->
    evtF asegs RNG POST (STO 0x95860 m1 x1 (Z_to_bv 64 (s * SVK)) x9 x10 x12 x15 (Z_to_bv 64 pos) x21 x22 x23 x24 x25 x26 x27
                             (Z_to_bv 64 s) x30 x31).
Proof.
